import json, copy

json_file = "/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-53acb1f1.json"
demo_data = json.load(open(json_file))
demo_expected = demo_data[0]['output']

def transform(grid):
    import collections
    if not grid or not grid[0]:
        return grid
    color_counts = collections.Counter()
    for row in grid:
        for cell in row:
            color_counts[cell] += 1
    bg_color = color_counts.most_common(1)[0][0]
    rows, cols = len(grid), len(grid[0])
    output = copy.deepcopy(grid)
    for r in range(rows):
        for c in range(1, cols - 1):
            if output[r][c] == bg_color and output[r][c-1] != bg_color and output[r][c+1] != bg_color:
                output[r][c] = 2
    return output

# Many copy deep copies
input_fresh = demo_data[0]['input']
result_raw = transform(input_fresh)
result = result_raw  # Just point to it

# Deep check one by one
print("Element-by-element check:")
errors = []
for r in range(len(result)):
    for c in range(len(result[r])):
        if result[r][c] != demo_expected[r][c]:
            errors.append((r, c, result[r][c], demo_expected[r][c]))

print(f"Number of mismatches: {len(errors)}")
if errors:
    print("First 10 errors:")
    for e in errors[:10]:
        print(f"  ({e[0]},{e[1]}): got={e[2]!r}, expect={e[3]!r}")
else:
    print("No errors found!")
    print(f"Peak equality: {result == demo_expected}")

